import{_ as e,o as r,c as f,a3 as t}from"./chunks/framework.CJlOecQn.js";const u=JSON.parse('{"title":"أساسيات تكاليف المعيشة","description":"ما تذكره الجهات الرسمية عن الضرائب والأسعار والكهرباء والماء والمواصلات ورسوم البطاقة الصحية في قطر، وأين تجد الأرقام الحالية.","frontmatter":{"title":"أساسيات تكاليف المعيشة","description":"ما تذكره الجهات الرسمية عن الضرائب والأسعار والكهرباء والماء والمواصلات ورسوم البطاقة الصحية في قطر، وأين تجد الأرقام الحالية.","lastChecked":"2026-10","sourceCount":8},"headers":[],"relativePath":"ar/guide/cost-of-living.md","filePath":"ar/guide/cost-of-living.md"}'),o={name:"ar/guide/cost-of-living.md"};function s(l,a,n,i,h,c){return r(),f("div",null,[...a[0]||(a[0]=[t('<h1 id="أساسيات-تكاليف-المعيشة" tabindex="-1">أساسيات تكاليف المعيشة <a class="header-anchor" href="#أساسيات-تكاليف-المعيشة" aria-label="Permalink to &quot;أساسيات تكاليف المعيشة&quot;">​</a></h1><p>تقتصر هذه الصفحة على الأرقام المنشورة من جهات رسمية. ولا تذكر متوسط الإيجارات أو تكلفة مشتريات البقالة، لأن البيانات الرسمية المستخدمة هنا تبين تغير الأسعار، لا تكلفة مسكن أو سلة مشتريات بعينها.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></p><h2 id="الضرائب" tabindex="-1">الضرائب <a class="header-anchor" href="#الضرائب" aria-label="Permalink to &quot;الضرائب&quot;">​</a></h2><ul><li>لا توجد ضريبة على دخل الأفراد. وتذكر الهيئة العامة للضرائب أن الأفراد لا يدفعون ضريبة على الرواتب أو الأجور أو الدخل الشخصي.<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup></li><li>ترفع الضريبة الانتقائية أسعار بعض السلع. فالتبغ ومنتجاته ومشروبات الطاقة تخضع لضريبة قدرها 100 بالمئة من السعر القياسي أو سعر البيع بالتجزئة قبل الضريبة، أيهما أعلى.<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></li><li>تُفرض الضريبة على المشروبات المحلاة بحسب محتوى السكر: 0.77 ريال قطري لكل لتر عند 5 إلى 7.99 غرام من السكر لكل 100 مل، و1.06 ريال قطري لكل لتر عند 8 غرامات فأكثر. وتُعفى المشروبات التي يقل سكرها عن 5 غرامات، والمشروبات التي تحتوي على محليات صناعية فقط دون سكر مضاف.<sup class="footnote-ref"><a href="#fn3" id="fnref3:1">[3]</a></sup></li></ul><h2 id="اتجاه-الأسعار" tabindex="-1">اتجاه الأسعار <a class="header-anchor" href="#اتجاه-الأسعار" aria-label="Permalink to &quot;اتجاه الأسعار&quot;">​</a></h2><p>يتتبع الرقم القياسي لأسعار المستهلك الصادر عن مجلس التخطيط الوطني تغير الأسعار مقارنة بالشهر السابق والشهر نفسه من العام الماضي. وأحدث إصدار عُثر عليه عند مراجعة هذه الصفحة يغطي يونيو 2026.<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1]</a></sup></p><ul><li>بلغ الرقم القياسي 110.12 نقطة (سنة الأساس 2018)، بارتفاع 0.06 بالمئة عن مايو 2026 و2.21 بالمئة عن يونيو 2025.<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1]</a></sup></li><li>مقارنة بيونيو 2025، ارتفعت مجموعة الأغذية والمشروبات 12.74 بالمئة، ومجموعة السكن والماء والكهرباء والغاز وأنواع الوقود الأخرى 2.67 بالمئة.<sup class="footnote-ref"><a href="#fn1" id="fnref1:3">[1]</a></sup></li><li>انخفضت مجموعة النقل 0.92 بالمئة خلال الفترة نفسها.<sup class="footnote-ref"><a href="#fn1" id="fnref1:4">[1]</a></sup></li></ul><p>ويرجع المجلس الزيادة إلى التحديات الإقليمية التي أثرت في سلاسل الإمداد الدولية.<sup class="footnote-ref"><a href="#fn1" id="fnref1:5">[1]</a></sup></p><h2 id="الكهرباء-والماء" tabindex="-1">الكهرباء والماء <a class="header-anchor" href="#الكهرباء-والماء" aria-label="Permalink to &quot;الكهرباء والماء&quot;">​</a></h2><p>تتضمن صفحة التعرفة لدى كهرماء حاسبة للكهرباء والماء، يمكنك من خلالها تقدير الفاتورة وفق الأسعار الحالية. وتجد تفاصيل الانتقال وسداد الفواتير في صفحة <a href="./housing-and-utilities">السكن والإيجار</a>.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup></p><h2 id="التنقل" tabindex="-1">التنقل <a class="header-anchor" href="#التنقل" aria-label="Permalink to &quot;التنقل&quot;">​</a></h2><ul><li>تذكر قطر للسياحة أنه يمكنك استخدام مترو الدوحة طوال اليوم بحد أقصى 6 ريالات قطرية.<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup></li><li>تشتري بطاقة السفر من أجهزة البيع في المحطات، كما تبيعها بعض المتاجر.<sup class="footnote-ref"><a href="#fn5" id="fnref5:1">[5]</a></sup></li><li>تشغل مواصلات حافلات كروة. استخدم تطبيق Karwa Journey Planner لتخطيط رحلتك، وراجع صفحة <a href="./transport">المواصلات</a> لمزيد من التفاصيل.<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup></li></ul><h2 id="البطاقة-الصحية" tabindex="-1">البطاقة الصحية <a class="header-anchor" href="#البطاقة-الصحية" aria-label="Permalink to &quot;البطاقة الصحية&quot;">​</a></h2><p>تذكر مؤسسة حمد الطبية أن رسم البطاقة الصحية 100 ريال قطري للمقيمين، كبارًا وصغارًا، و50 ريالًا قطريًا للمواطنين القطريين ومواطني دول مجلس التعاون وعمال المنازل. كما تذكر أن رسم البطاقة الجديدة للعمال اليدويين 50 ريالًا قطريًا.<sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup></p><p>ويبلغ رسم استبدال البطاقة المفقودة لغير القطريين 100 ريال قطري إذا كانت سارية، و200 ريال قطري إذا كانت منتهية.<sup class="footnote-ref"><a href="#fn7" id="fnref7:1">[7]</a></sup></p><h2 id="الأجور" tabindex="-1">الأجور <a class="header-anchor" href="#الأجور" aria-label="Permalink to &quot;الأجور&quot;">​</a></h2><p>يذكر كتاب الجيب للعامل الصادر عن اللجنة الوطنية لحقوق الإنسان عام 2021 أن الحد الأدنى للأجور 1,000 ريال قطري شهريًا، إضافة إلى 500 ريال على الأقل للسكن و300 ريال على الأقل للطعام إذا لم يوفرهما صاحب العمل. راجع المبالغ الحالية لدى وزارة العمل.<sup class="footnote-ref"><a href="#fn8" id="fnref8">[8]</a></sup></p><p>انظر أيضًا: <a href="./housing-and-utilities">السكن والإيجار</a>، <a href="./work-and-labour-rights">العمل وحقوق العمال</a>، <a href="./transport">المواصلات</a>، <a href="./health">الصحة</a>.</p><h2 id="المصادر" tabindex="-1">المصادر <a class="header-anchor" href="#المصادر" aria-label="Permalink to &quot;المصادر&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>مجلس التخطيط الوطني، <a href="https://www.npc.qa/en/statistics/pages/news/07082026.aspx" target="_blank" rel="noreferrer">الرقم القياسي لأسعار المستهلك لشهر يونيو 2026</a>. آخر تحقق: 2026-10. <a href="#fnref1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:4" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:5" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn2" class="footnote-item"><p>الهيئة العامة للضرائب، <a href="https://gta.gov.qa/en/investors" target="_blank" rel="noreferrer">المستثمرون</a>. آخر تحقق: 2026-10. <a href="#fnref2" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn3" class="footnote-item"><p>الهيئة العامة للضرائب، <a href="https://gta.gov.qa/en/taxes-info" target="_blank" rel="noreferrer">معلومات الضرائب</a>. آخر تحقق: 2026-10. <a href="#fnref3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref3:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn4" class="footnote-item"><p>كهرماء، <a href="https://www.km.qa/CustomerService/Pages/Tariff.aspx" target="_blank" rel="noreferrer">التعرفة</a>. آخر تحقق: 2026-10. <a href="#fnref4" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn5" class="footnote-item"><p>قطر للسياحة، <a href="https://visitqatar.com/intl-en/plan-your-trip/getting-around/doha-metro" target="_blank" rel="noreferrer">دليل مترو الدوحة: التذاكر والخريطة ومواعيد الخدمة</a>. آخر تحقق: 2026-10. <a href="#fnref5" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref5:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn6" class="footnote-item"><p>مواصلات، <a href="https://www.mowasalat.com/our-service/public-bus-transportation/" target="_blank" rel="noreferrer">النقل العام بالحافلات</a>. آخر تحقق: 2026-10. <a href="#fnref6" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn7" class="footnote-item"><p>مؤسسة حمد الطبية، <a href="https://www.hamad.qa/EN/Patient-Information/How-To-Get-A-Health-Card/Pages/default.aspx" target="_blank" rel="noreferrer">الحصول على البطاقة الصحية وتجديدها</a>. آخر تحقق: 2026-10. <a href="#fnref7" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref7:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn8" class="footnote-item"><p>اللجنة الوطنية لحقوق الإنسان، <a href="https://www.nhrc-qa.org/storage/publications/file_6666d6f57f82d_1718015733.pdf" target="_blank" rel="noreferrer">كتاب الجيب للعامل، الطبعة السادسة، ديسمبر 2021</a>. آخر تحقق: 2026-10. <a href="#fnref8" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li></ol></section>',21)])])}const d=e(o,[["render",s]]);export{u as __pageData,d as default};
